import { Component, h, Prop, Element, State, EventEmitter, Event, Listen, Watch, Method, forceUpdate } from '@stencil/core';

@Component({
  tag: 'std-range',
  styleUrl: 'std-range.css',
  shadow: true
})
export class StdRangeComponent {
  @Prop() min: string;
  @Prop() max: string;
  @Prop({ mutable: true }) initialValue: string;
  @Prop({ mutable: true }) finalValue: string;
  @Prop() unitBefore: string;
  @Prop() unitAfter: string;

  @Element() el: HTMLElement;
  @State() isOpen = false;

  @Event() changeRange: EventEmitter;

  percentInitial: number;
  percentFinal: number;

  isErrorInitial: boolean = false;
  isErrorFinal: boolean = false;

  initialValueInput: string;
  finalValueInput: string;

  inputElement: HTMLStdInputElement;
  menuElement: HTMLDivElement;
  iconElement: HTMLElement;

  componentWillLoad() {
    // this.initialValueInput = this.initialValue;
    // this.finalValueInput = this.finalValue;
  }

  componentDidLoad() {
    this.updateRangeSliders();
  }

  private formatCurrency(value: string) {
    const convert = Number(value);
    if (isNaN(convert)) return '';
    return new Intl.NumberFormat().format(convert).toString();
  }

  private updateRangeSliders() {
    const rangeSliders = this.el.shadowRoot.querySelectorAll('.js-range');
    rangeSliders.forEach(range => {
      const initialRange = range.querySelector('.js-range-initial') as HTMLInputElement;
      const finalRange = range.querySelector('.js-range-final') as HTMLInputElement;

      this.initialValue = initialRange.value;
      this.finalValue = finalRange.value;

      initialRange.addEventListener('input', () => this.handleInputChange(initialRange, finalRange));
      finalRange.addEventListener('input', () => this.handleInputChange(initialRange, finalRange));
      this.updateRangeTrack(range as HTMLElement, initialRange, finalRange);
    });
  }

  private handleInputChange(initialRange: HTMLInputElement, finalRange: HTMLInputElement) {
    if (parseInt(initialRange.value) > parseInt(finalRange.value)) {
      initialRange.value = finalRange.value;
    } else if (parseInt(finalRange.value) < parseInt(initialRange.value)) {
      finalRange.value = initialRange.value;
    }
    this.updateRangeTrack(initialRange.parentElement, initialRange, finalRange);
  }

  private updateRangeTrack(rangeElement: HTMLElement, initialRange: HTMLInputElement, finalRange: HTMLInputElement) {
    const rangeTrack = rangeElement.querySelector('.js-range-track') as HTMLElement;
    this.percentInitial = (parseInt(initialRange.value) / parseInt(this.max)) * 100;
    this.percentFinal = (parseInt(finalRange.value) / parseInt(this.max)) * 100;
    rangeTrack.style.background = `linear-gradient(to right, #8F8F8F ${this.percentInitial}%, #127277 ${this.percentInitial}%, #127277 ${this.percentFinal}%, #8F8F8F ${this.percentFinal}%)`;
  }

  private toggleCollapse() {
    this.isOpen = !this.isOpen;
  }

  private getValueInput() {
    return this.initialValueInput && this.finalValueInput ? `${this.formatCurrency(this.initialValueInput)} - ${this.formatCurrency(this.finalValueInput)}` : '';
  }
  private updatePropsFromState(isInitial: boolean) {
    isInitial ? (this.isErrorInitial = false) : (this.isErrorFinal = false);
    this.initialValue = Math.round(parseInt(this.max) * (this.percentInitial * 0.01)).toString();
    this.finalValue = Math.round(parseInt(this.max) * (this.percentFinal * 0.01)).toString();
    this.renderSlider();
  }

  @Listen('click', { target: 'document' })
  checkForClickOutside(ev: PointerEvent): void {
    const path = ev.composedPath();
    if (this.isOpen && !path.includes(this.inputElement) && !path.includes(this.menuElement) && !path.includes(this.iconElement)) {
      this.isOpen = false;
    }
  }

  @Watch('isOpen')
  emitChangeRange() {
    this.initialValue = this.isErrorInitial ? this.initialValueInput : this.initialValue;
    this.finalValue = this.isErrorFinal ? this.finalValueInput : this.finalValue;

    this.changeRange.emit({
      initialValue: this.initialValue,
      finalValue: this.finalValue
    });

    this.initialValueInput = this.initialValue;
    this.finalValueInput = this.finalValue;

    this.isErrorFinal = this.isErrorInitial = false;
    this.renderSlider();
  }

  clearInput(isInitial: boolean) {
    if (isInitial) {
      this.initialValue = this.min;
      this.isErrorInitial = false;
    } else {
      this.finalValue = this.max;
      this.isErrorFinal = false;
    }
    this.renderSlider();
  }

  validateIsOutOfRange(e, isInitial: boolean) {
    isInitial ? (this.isErrorInitial = false) : (this.isErrorFinal = false);
    const value = (e.target as HTMLInputElement).value;
    let newValue = String(parseInt(value));
    if (isNaN(Number(newValue)) || newValue === '') {
      newValue = '';
      isInitial ? (this.isErrorInitial = true) : (this.isErrorFinal = true);
    }
    if (Number(newValue) > Number(this.max) || Number(newValue) < Number(this.min)) {
      isInitial ? (this.isErrorInitial = true) : (this.isErrorFinal = true);
    }
    if (isInitial && Number(newValue) > Number(this.finalValue)) {
      this.isErrorInitial = true;
    }
    if (!isInitial && Number(newValue) < Number(this.initialValue)) {
      this.isErrorFinal = true;
    }
    (e.target as HTMLInputElement).value = newValue;
    isInitial ? (this.initialValue = newValue) : (this.finalValue = newValue);
    this.renderSlider();
  }

  onlyNumbers(e: KeyboardEvent) {
    const allowedKeys = ['Backspace', 'Tab', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Delete'];
    if ((e.key >= '1' && e.key <= '9') || allowedKeys.includes(e.key) || (e.key == '0' && (e.target as HTMLInputElement).value.length > 0)) {
      return;
    }
    e.preventDefault();
  }

  renderSlider() {
    const rangeTrack = this.el.shadowRoot.querySelector('.js-range-track') as HTMLElement;
    const min = parseInt(this.min);
    const max = parseInt(this.max);
    const init = this.isErrorInitial ? min : parseInt(this.initialValue);
    const final = this.isErrorFinal ? max : parseInt(this.finalValue);

    this.percentInitial = ((init - min) / (max - min)) * 100;
    this.percentFinal = ((final - min) / (max - min)) * 100;

    rangeTrack.style.background = `linear-gradient(to right, #8F8F8F ${this.percentInitial}%, #127277 ${this.percentInitial}%, #127277 ${this.percentFinal}%, #8F8F8F ${this.percentFinal}%)`;
    forceUpdate(this);
  }

  @Method()
  async reset() {
    this.initialValueInput = undefined;
    this.finalValueInput = undefined;
    this.initialValue = this.min;
    this.finalValue = this.max;
    this.changeRange.emit({
      initialValue: this.initialValueInput,
      finalValue: this.finalValueInput
    });
    this.renderSlider();
  }

  @Method()
  async setRange(initialValue: string, finalValue: string) {
    this.initialValueInput = initialValue;
    this.finalValueInput = finalValue;
    this.initialValue = initialValue;
    this.finalValue = finalValue;
    this.changeRange.emit({
      initialValue: this.initialValueInput,
      finalValue: this.finalValueInput
    });
    this.renderSlider();
  }

  render() {
    return (
      <div class={`flex css-select flex-col gap-1 w-full css-collapse js-collapse relative ${this.isOpen ? 'is-open' : ''}`}>
        <div class="css-collapse-header js-collapse-header relative">
          <std-input
            onKeyDown={e => e.preventDefault()}
            ref={el => (this.inputElement = el)}
            value={this.getValueInput()}
            placeholder="Ingresa un rango"
            label="Importe"
            onClick={() => this.toggleCollapse()}
          />
          <div class="absolute right-3 bottom-3 w-6 h-6 bg-limit-range cursor-pointer" ref={el => (this.iconElement = el)} onClick={() => this.toggleCollapse()} />
        </div>
        <div ref={el => (this.menuElement = el)} class="css-collapse-body hidden js-collapse-body absolute top-[80px] left-0 shadow-modal bg-white rounded-lg p-5 z-10 w-full">
          <div class="js-range flex flex-col gap-3 w-full">
            <div class="flex flex-col gap-3">
              <div class="grid grid-cols-2 gap-4">
                <div>
                  <std-input
                    type="number"
                    min={this.min}
                    max={this.finalValue}
                    value={this.initialValue}
                    icon={this.isErrorInitial ? 'error' : 'default'}
                    helperText={this.isErrorInitial ? 'Rango inválido' : undefined}
                    status={this.isErrorInitial ? 'error' : 'default'}
                    onIconClick={() => this.clearInput(true)}
                    onKeyDown={e => this.onlyNumbers(e)}
                    onChangeEvent={e => this.validateIsOutOfRange(e, true)}
                    label="Desde"
                    classes="no-numeric-arrows"
                  />
                </div>
                <div>
                  <std-input
                    type="number"
                    min={this.initialValue}
                    max={this.max}
                    value={this.finalValue}
                    icon={this.isErrorFinal ? 'error' : 'default'}
                    helperText={this.isErrorFinal ? 'Rango inválido' : undefined}
                    status={this.isErrorFinal ? 'error' : 'default'}
                    onIconClick={() => this.clearInput(false)}
                    onKeyDown={e => this.onlyNumbers(e)}
                    onChangeEvent={e => this.validateIsOutOfRange(e, false)}
                    label="Hasta"
                    classes="no-numeric-arrows"
                  />
                </div>
              </div>
            </div>
            <div class="relative flex flex-col gap-4 w-full ">
              <div class="w-full flex items-center justify-between px-4 pb-1">
                {[...Array(5)].map((_, index) => (
                  <span key={index} class="h-2 w-[1px] bg-border-default block rounded-sm"></span>
                ))}
              </div>
              <div class="relative">
                <div class="js-range-track absolute inset-x-0 top-1/2 left-1/2 -tranlate-y-1/2 -translate-x-2/4 h-1 rounded-lg w-full"></div>
                <input
                  class="js-range-initial css-range-input appearance-none outline-none absolute inset-0 bg-transparent pointer-events-none -top-[10px]"
                  type="range"
                  min={this.min}
                  max={this.max}
                  value={this.isErrorInitial ? this.min : this.initialValue}
                  onInput={() => this.updatePropsFromState(true)}
                />
                <input
                  class="js-range-final css-range-input appearance-none outline-none absolute inset-0 bg-transparent pointer-events-none -top-[10px]"
                  type="range"
                  min={this.min}
                  max={this.max}
                  value={this.isErrorFinal ? this.max : this.finalValue}
                  onInput={() => this.updatePropsFromState(false)}
                />
              </div>
              <div class="flex justify-between items-center w-full">
                <span class="text-soft text-sm">min</span>
                <span class="text-soft text-sm">max</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }
}
